create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, exam_level text not null default 'CET-4', exam_date date, timezone text not null default 'Asia/Shanghai', reminder_time time not null default '20:00', created_at timestamptz not null default now());
create table public.word_lists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, is_sample boolean not null default false, created_at timestamptz not null default now());
create table public.words (id uuid primary key default gen_random_uuid(), list_id uuid not null references public.word_lists(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, word text not null, meaning text not null, example text default '', level text default 'CET', tags text[] default '{}', created_at timestamptz not null default now(), unique(user_id,word));
create table public.word_progress (user_id uuid not null references auth.users(id) on delete cascade, word_id uuid not null references public.words(id) on delete cascade, stage integer not null default 0, due_at timestamptz not null default now(), last_result text, reviews integer not null default 0, primary key(user_id,word_id));
create table public.study_events (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, word_id uuid not null references public.words(id) on delete cascade, result text not null check(result in ('again','fuzzy','known')), reviewed_at timestamptz not null default now());
create table public.daily_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, task_date date not null, new_target integer not null, completed integer not null default 0, unique(user_id,task_date));
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, endpoint text not null unique, p256dh text not null, auth text not null, device_name text not null default 'Browser', active boolean not null default true, last_sent_at timestamptz, created_at timestamptz not null default now());
create index idx_words_user on public.words(user_id); create index idx_progress_due on public.word_progress(user_id,due_at); create index idx_push_due on public.push_subscriptions(user_id,active);
alter table public.profiles enable row level security; alter table public.word_lists enable row level security; alter table public.words enable row level security; alter table public.word_progress enable row level security; alter table public.study_events enable row level security; alter table public.daily_tasks enable row level security; alter table public.push_subscriptions enable row level security;
create policy "own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own lists" on public.word_lists for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own words" on public.words for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own progress" on public.word_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own events" on public.study_events for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own tasks" on public.daily_tasks for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own pushes" on public.push_subscriptions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare l uuid; begin insert into profiles(id) values(new.id); insert into word_lists(user_id,name,is_sample) values(new.id,'四六级示例词包',true) returning id into l; insert into words(list_id,user_id,word,meaning,example,level,tags) values(l,new.id,'abandon','放弃；抛弃','Never abandon your hope.','CET-4',array['核心']),(l,new.id,'compelling','引人入胜的','She made a compelling argument.','CET-6',array['高频']),(l,new.id,'inevitable','不可避免的','Change is inevitable.','CET-6',array['阅读']); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
